"""Reviewed statements for arrays, algorithms and contest problems."""
from catalog import add, ARRAY_INPUT, MOD_OUTPUT, INT_NOTE

for key, body, output, examples in [
 ('array_sum','Найдите сумму всех элементов массива. Каждый элемент учитывается один раз, в том числе отрицательные числа и повторяющиеся значения.','сумму элементов',[('5\n3 -2 0 3 6','10','3 − 2 + 0 + 3 + 6 = 10.'),('2\n-4 -7','-11','Сумма может быть отрицательной.')]),
 ('array_max','Найдите наибольшее значение среди элементов массива. Если оно встречается несколько раз, значение всё равно выводится один раз.','наибольший элемент',[('4\n2 9 -3 9','9','Максимальное значение равно 9.'),('3\n-8 -2 -5','-2','Среди отрицательных чисел наибольшее — −2.')]),
 ('array_min','Найдите наименьшее значение среди элементов массива. Повторные вхождения не меняют ответ.','наименьший элемент',[('4\n2 9 -3 9','-3','Наименьшее значение равно −3.'),('1\n7','7','В массиве из одного элемента этот элемент является минимумом.')]),
 ('positive','Посчитайте элементы массива, строго большие нуля. Ноль положительным числом не считается. Повторяющиеся положительные элементы учитываются отдельно.','количество положительных элементов',[('5\n-1 0 2 2 7','3','Положительны два вхождения числа 2 и число 7.'),('3\n-5 0 -2','0','Положительных элементов нет.')]),
 ('even_count','Посчитайте элементы массива, которые делятся на 2 без остатка. Ноль и отрицательные чётные числа также учитываются.','количество чётных элементов',[('5\n-4 -1 0 3 8','3','Чётные элементы: −4, 0 и 8.'),('3\n1 3 5','0','Все элементы нечётные.')]),
 ('distinct_count','Определите, сколько различных значений встречается в массиве. Все вхождения одного значения вместе считаются одним различным значением.','количество различных значений',[('6\n3 3 -1 0 -1 3','3','Различные значения: −1, 0 и 3.'),('3\n8 8 8','1','Есть только одно различное значение.')]),
]:
    add(key,body,ARRAY_INPUT,'Выведите одно целое число — '+output+'.',examples,INT_NOTE if key=='array_sum' else '')

add('average','Найдите среднее арифметическое элементов массива: сумму всех N элементов, делённую на N. Результат может быть дробным или отрицательным.',ARRAY_INPUT,
    'Выведите среднее арифметическое с ровно шестью цифрами после десятичной точки, округлив до ближайшего значения с шестью знаками.',
    [('4\n1 2 3 4','2.500000','Сумма равна 10; 10 / 4 = 2.5.'),('3\n-1 0 0','-0.333333','Среднее равно −1/3.')],INT_NOTE)
add('second_max','В массиве все значения попарно различны. Найдите второе по величине значение: после упорядочивания по убыванию оно находится на второй позиции.',
    ARRAY_INPUT.replace('1 ≤ N','2 ≤ N')+' Все элементы попарно различны.', 'Выведите второй по величине элемент массива.',
    [('4\n8 1 5 3','5','По убыванию: 8, 5, 3, 1. Второе значение — 5.'),('2\n-7 -2','-7','Наибольший элемент — −2, следующий — −7.')])
add('reverse_array','Выведите элементы массива в обратном порядке: от последнего к первому. Значения элементов и число их вхождений сохраняются.',ARRAY_INPUT,
    'Выведите N целых чисел в одной строке через пробел — массив в обратном порядке.',
    [('4\n3 -1 3 8','8 3 -1 3','Последний элемент становится первым.'),('1\n5','5','Массив из одного элемента не меняется.')])
add('prefix','Для каждого i от 1 до N вычислите сумму первых i элементов массива. Полученные N сумм образуют массив префиксных сумм; исходные элементы могут быть отрицательными.',ARRAY_INPUT,
    'Выведите N целых чисел через пробел. На позиции i должна стоять сумма a₁ + a₂ + … + aᵢ.',
    [('4\n2 -3 5 1','2 -1 4 5','Последовательные суммы: 2; 2 − 3; 2 − 3 + 5; 2 − 3 + 5 + 1.'),('3\n0 0 0','0 0 0','Все префиксные суммы равны нулю.')],INT_NOTE)

for key, direction, answer in [('sort_asc','неубывающем','-1 2 2 7'),('sort_desc','невозрастающем','7 2 2 -1')]:
    add(key,'Расположите элементы массива в '+direction+' порядке. Сохраните все повторяющиеся элементы.',ARRAY_INPUT,
        'Выведите N целых чисел через пробел — упорядоченный массив.',
        [('4\n2 -1 7 2',answer,'Оба вхождения числа 2 остаются в ответе.'),('1\n0','0','Единственный элемент уже упорядочен.')])
NK_INPUT='В первой строке даны N и K (1 ≤ K ≤ N ≤ 100000). Во второй строке даны N целых чисел aᵢ (−10^9 ≤ aᵢ ≤ 10^9).'
add('kth','Упорядочите мысленно массив по неубыванию и найдите элемент на позиции K. Позиции нумеруются с 1. Одинаковые значения занимают отдельные позиции.',NK_INPUT,
    'Выведите одно целое число — K-й элемент в упорядоченном массиве.',
    [('5 3\n8 2 2 -1 6','2','После сортировки: −1, 2, 2, 6, 8; третий элемент равен 2.'),('3 1\n9 4 7','4','При K = 1 требуется минимум.')])
add('median','Упорядочите массив по неубыванию и найдите его нижнюю медиану. При нечётном N это центральный элемент, при чётном — левый из двух центральных. Повторяющиеся элементы учитываются отдельно; усреднять центральные значения не нужно.',ARRAY_INPUT,
    'Выведите элемент на позиции ⌊(N + 1) / 2⌋ в упорядоченном массиве. Нумерация начинается с 1.',
    [('4\n9 1 7 3','3','После сортировки: 1, 3, 7, 9. Нижняя медиана — 3.'),('5\n4 2 8 2 9','4','После сортировки центральный, третий элемент равен 4.')])
add('inversions','Инверсией называется пара позиций (i, j), для которой i < j и aᵢ > aⱼ. Посчитайте все такие пары. Равные элементы инверсию не образуют; одна позиция может участвовать в нескольких парах.',ARRAY_INPUT.replace('100000','1000'),
    'Выведите одно целое число — количество инверсий.',
    [('4\n3 1 2 2','3','Инверсии образуют пары позиций (1, 2), (1, 3), (1, 4).'),('3\n1 1 2','0','Массив уже упорядочен по неубыванию.')])
add('sort_even','Оставьте в массиве только чётные элементы и расположите их по неубыванию. Ноль и отрицательные чётные числа также подходят. Все повторения подходящих элементов сохраняются.',ARRAY_INPUT,
    'Выведите выбранные элементы через пробел. Если чётных элементов нет, выведите одно число `0`.',
    [('6\n3 -2 4 0 4 7','-2 0 4 4','Нечётные элементы удаляются; оба вхождения 4 остаются.'),('3\n1 3 5','0','Для отсутствия чётных элементов предусмотрен ответ 0.')])
add('closest','Выберите K элементов массива с наименьшим расстоянием до нуля, то есть с наименьшим абсолютным значением. При равных абсолютных значениях раньше выбирается элемент, стоящий раньше во входном массиве. После выбора расположите выбранные значения по неубыванию.',NK_INPUT,
    'Выведите K выбранных целых чисел через пробел в неубывающем порядке. Повторения сохраняются.',
    [('5 3\n4 -1 2 -2 0','-1 0 2','Сначала выбираются 0 и −1. Из 2 и −2 выбирается 2, так как оно стоит раньше.'),('3 1\n-3 3 5','-3','У −3 и 3 одинаковое расстояние до нуля; раньше находится −3.')])
add('mode','Найдите значение, которое встречается в массиве чаще всего. Если максимальная частота одинакова у нескольких значений, выберите наименьшее из них.',ARRAY_INPUT,
    'Выведите одно целое число — выбранное значение. Его частоту выводить не нужно.',
    [('5\n4 2 4 2 9','2','2 и 4 встречаются по два раза; выбирается меньшее значение 2.'),('3\n7 7 1','7','Значение 7 встречается чаще остальных.')])
add('sort_unique','Удалите повторные вхождения значений массива и выведите оставшиеся различные значения по возрастанию. Каждое значение должно появиться в ответе ровно один раз.',ARRAY_INPUT,
    'Выведите различные значения через пробел в строго возрастающем порядке. Их количество отдельно выводить не нужно.',
    [('6\n3 -1 3 0 -1 8','-1 0 3 8','Повторы −1 и 3 удалены.'),('3\n5 5 5','5','Остаётся одно значение.')])
add('merge','Даны два массива, каждый уже упорядочен по неубыванию. Объедините их в один массив, также упорядоченный по неубыванию. Все элементы обоих массивов, включая повторяющиеся, должны войти в ответ.',
    'В первой строке даны длины N и M (1 ≤ N, M ≤ 100000). Во второй строке даны N элементов первого массива, в третьей — M элементов второго. Все элементы целые, от −10^9 до 10^9; каждый массив упорядочен по неубыванию.',
    'Выведите N + M целых чисел через пробел — объединённый упорядоченный массив.',
    [('3 2\n1 3 3\n2 3','1 2 3 3 3','В ответ входят все три вхождения числа 3.'),('1 2\n-2\n-5 0','-5 -2 0','Элементы обоих массивов располагаются по неубыванию.')])

add('prime','Целое число больше 1 называется простым, если его единственные положительные делители — 1 и само число. Определите, является ли заданное N простым.',
    'Дано одно целое число N (2 ≤ N ≤ 10^9).','Выведите `YES`, если N простое, и `NO` в противном случае.',
    [('2','YES','У числа 2 только два положительных делителя: 1 и 2.'),('21','NO','21 делится на 3 и 7.')])
for key,what,ans in [('divisor_count','количество','6'),('divisor_sum','сумму','28')]:
    add(key,'Найдите '+what+' всех положительных делителей числа N. Делитель — целое положительное число, на которое N делится без остатка. Каждый делитель учитывается ровно один раз, включая 1 и N.',
        'Дано одно целое число N (1 ≤ N ≤ 10^9).','Выведите одно целое число — '+what+' положительных делителей N.',
        [('12',ans,'Положительные делители 12: 1, 2, 3, 4, 6, 12.'),('1','1','У единицы единственный положительный делитель — 1.')],INT_NOTE if key=='divisor_sum' else '')
add('digit_sum','Найдите сумму цифр десятичной записи неотрицательного целого числа N. Каждое вхождение цифры учитывается отдельно.',
    'Дано целое число N (0 ≤ N ≤ 10^18), записанное без ведущих нулей, кроме самого числа 0.','Выведите одно целое число — сумму цифр N.',
    [('10027','10','1 + 0 + 0 + 2 + 7 = 10.'),('0','0','Единственная цифра числа 0 равна нулю.')])
add('digit_count','Определите количество цифр в десятичной записи неотрицательного целого числа N. У числа 0 одна цифра.',
    'Дано целое число N (0 ≤ N ≤ 10^18), записанное без ведущих нулей, кроме самого числа 0.','Выведите количество цифр N.',
    [('10027','5','В записи пять цифр, включая два нуля.'),('0','1','Запись нуля состоит из одной цифры.')])

for key, what, answer in [('rectangle_area','площадь','15'),('rectangle_perimeter','периметр','16')]:
    add(key,'У прямоугольника длины соседних сторон равны A и B. Найдите его '+what+'. Длины заданы в одинаковых единицах измерения.',
        'В одной строке даны два целых числа A и B (1 ≤ A, B ≤ 10^9).','Выведите одно целое число — '+what+' прямоугольника.',
        [('3 5',answer,'Стороны прямоугольника равны 3 и 5.'),('1 1','1' if key=='rectangle_area' else '4','Получается квадрат со стороной 1.')],INT_NOTE)
add('triangle_area','Даны длина основания B треугольника и высота H, опущенная на это основание. Высота перпендикулярна прямой, содержащей основание. Найдите площадь треугольника.',
    'В одной строке даны целые B и H (1 ≤ B, H ≤ 10^9).','Выведите площадь с ровно одной цифрой после десятичной точки: `.0` для целого значения или `.5` для полуцелого.',
    [('3 4','6.0','Площадь равна половине произведения основания на высоту: 3 · 4 / 2 = 6.'),('3 5','7.5','Площадь может быть нецелой.')],INT_NOTE)
add('distance','На плоскости заданы две точки с декартовыми координатами (x₁, y₁) и (x₂, y₂). Найдите длину прямого отрезка между ними. Точки могут совпадать.',
    'В одной строке даны четыре целых числа x₁, y₁, x₂, y₂. Каждая координата находится в диапазоне от −10000 до 10000.',
    'Выведите расстояние с ровно шестью цифрами после десятичной точки, округлив до ближайшего значения с шестью знаками.',
    [('0 0 3 4','5.000000','Разности координат равны 3 и 4; длина отрезка равна 5.'),('2 -1 2 -1','0.000000','Совпадающие точки находятся на расстоянии 0.')])
add('circle_area','Дан радиус R круга. Найдите площадь круга. Используйте математическую константу π с достаточной точностью, а не приближение 3.14.',
    'Дано одно целое число R (1 ≤ R ≤ 10000).','Выведите площадь с ровно шестью цифрами после десятичной точки, округлив до ближайшего значения с шестью знаками.',
    [('1','3.141593','Площадь круга единичного радиуса равна π.'),('2','12.566371','Площадь равна 4π.')])

add('coins','Имеется неограниченное количество монет номиналами 1, 5, 10 и 25. Наберите сумму S, используя как можно меньше монет. Сумма выбранных монет должна быть в точности равна S.',
    'Дано одно целое число S (1 ≤ S ≤ 1000000).','Выведите минимальное количество монет.',
    [('41','4','Можно взять монеты 25, 10, 5 и 1.'),('30','2','Подходят монеты 25 и 5.')])
add('pieces','Дана лента длины L. Из неё нужно вырезать как можно больше отрезков длины K. На разрезы длина не расходуется; остаток короче K использовать нельзя.',
    'В одной строке даны целые L и K (1 ≤ K ≤ L ≤ 10^9).','Выведите максимальное количество целых отрезков длины K.',
    [('17 5','3','Три отрезка займут длину 15; остаток 2 меньше 5.'),('12 4','3','Лента используется целиком.')])
add('budget','В магазине есть N товаров с заданными ценами. Каждый товар можно купить не более одного раза. Имея бюджет S, определите наибольшее количество товаров, которые можно купить. Потратить весь бюджет необязательно; товары с одинаковыми ценами считаются разными.',
    'В первой строке даны N и S (1 ≤ N ≤ 100000, 0 ≤ S ≤ 10^14). Во второй строке даны N целых цен aᵢ (1 ≤ aᵢ ≤ 10^9).',
    'Выведите максимальное количество товаров, суммарная стоимость которых не превышает S.',
    [('5 10\n7 2 3 8 4','3','Можно купить товары за 2, 3 и 4, потратив 9.'),('3 1\n2 4 3','0','Бюджета не хватает ни на один товар.')])
add('stairs','Лестница содержит N ступеней. Вы начинаете перед первой ступенью, на позиции 0, и должны попасть точно на позицию N. За один ход разрешено подняться на {steps_text} ступеней. Посчитайте различные последовательности ходов; порядок ходов имеет значение. Если достичь N невозможно, ответ равен нулю.',
    'Дано одно целое число N (1 ≤ N ≤ {limit}).',MOD_OUTPUT,[])
add('max_subarray','Выберите в массиве непустой непрерывный отрезок с наибольшей суммой элементов. Отрезок задаётся двумя позициями L и R, где 1 ≤ L ≤ R ≤ N, и включает все элементы между ними. Удалять элементы внутри отрезка нельзя.',ARRAY_INPUT,
    'Выведите максимальную сумму элементов такого отрезка. Если все элементы отрицательны, ответ также отрицателен: пустой отрезок выбирать нельзя.',
    [('6\n-2 3 -1 4 -5 2','6','Отрезок с позиции 2 по позицию 4 даёт 3 − 1 + 4 = 6.'),('3\n-8 -2 -5','-2','Лучший непустой отрезок состоит из одного элемента −2.')],INT_NOTE)

add('parity','Определите, является ли целое число N чётным. Чётное число делится на 2 без остатка; ноль также чётный.',
    'Дано целое число N (−10^9 ≤ N ≤ 10^9).','Выведите `Even` для чётного числа и `Odd` для нечётного. Регистр букв имеет значение.',
    [('0','Even','Ноль делится на 2 без остатка.'),('-7','Odd','Отрицательное число тоже может быть нечётным.')])
add('leap','Определите, является ли год Y високосным по правилам григорианского календаря. Год високосный, если делится на 400, либо делится на 4, но не делится на 100. Эти правила применяются ко всему заданному диапазону лет.',
    'Дано одно целое число Y (1 ≤ Y ≤ 10^9).','Выведите `YES` для високосного года и `NO` для обычного.',
    [('2000','YES','2000 делится на 400.'),('1900','NO','1900 делится на 100, но не на 400.')])
add('fizzbuzz','Для заданного числа N выполните правило FizzBuzz. Если N делится и на 3, и на 5, ответ — FizzBuzz. Если только на 3 — Fizz, если только на 5 — Buzz. Если ни на 3, ни на 5, ответом служит само N.',
    'Дано одно целое число N (1 ≤ N ≤ 1000000).','Выведите ровно один ответ для данного N: `FizzBuzz`, `Fizz`, `Buzz` или десятичную запись N. Соблюдайте регистр; последовательность от 1 до N выводить не нужно.',
    [('15','FizzBuzz','15 делится на 3 и на 5.'),('7','7','7 не делится ни на 3, ни на 5.')])
add('binary','Переведите неотрицательное целое число N из десятичной системы счисления в двоичную. В ответе используются только цифры 0 и 1, без ведущих нулей. Для N = 0 ответом служит 0.',
    'Дано целое число N (0 ≤ N ≤ 10^18).','Выведите двоичную запись N без префикса `0b` и без пробелов.',
    [('13','1101','13 = 8 + 4 + 1.'),('0','0','Ноль записывается одной цифрой.')])
add('reverse_number','Разверните порядок цифр десятичной записи модуля числа N, затем сохраните исходный знак. Ведущие нули полученного числа удаляются. Например, из −120 получается −21; для нуля ответ равен нулю.',
    'Дано целое число N (−10^18 ≤ N ≤ 10^18), записанное без лишних ведущих нулей.','Выведите полученное целое число в обычной десятичной записи.',
    [('1200','21','После разворота получается 0021; ведущие нули убираются.'),('-305','-503','Переворачиваются цифры, а знак минус сохраняется.')])

add('factorial','Факториал N — произведение всех целых чисел от 1 до N. По определению 0! = 1. Найдите остаток от деления N! на 1000000007.',
    'Дано целое число N (0 ≤ N ≤ 1000000).',MOD_OUTPUT,
    [('5','120','5! = 1 · 2 · 3 · 4 · 5 = 120.'),('0','1','Используется определение 0! = 1.')])
add('choose','Из N различных предметов нужно выбрать ровно K. Порядок выбранных предметов не имеет значения: два выбора различаются, только если отличаются составом. Найдите число способов выбора по модулю 1000000007.',
    'В одной строке даны целые N и K (0 ≤ K ≤ N ≤ 1000).',MOD_OUTPUT,
    [('4 2','6','Пары из предметов 1, 2, 3, 4: 12, 13, 14, 23, 24, 34.'),('5 0','1','Есть один способ выбрать ничего — пустой набор.')])
add('arrangements','Из N различных предметов составьте упорядоченную последовательность длины K без повторного использования предметов. Здесь порядок важен: последовательности (1, 2) и (2, 1) различны. Найдите количество последовательностей по модулю 1000000007.',
    'В одной строке даны целые N и K (0 ≤ K ≤ N ≤ 1000).',MOD_OUTPUT,
    [('4 2','12','Первый предмет можно выбрать 4 способами, второй — 3.'),('5 0','1','Существует одна пустая последовательность.')])
add('pascal','Выведите строку с номером N треугольника Паскаля. Нумерация строк начинается с 0: строка 0 состоит из одной единицы. Края каждой следующей строки равны 1, а внутренний элемент равен сумме двух соседних элементов предыдущей строки.',
    'Дано целое число N (0 ≤ N ≤ 30).','Выведите N + 1 целых чисел через пробел — строку N слева направо. Требуются точные значения, без взятия остатка.',
    [('4','1 4 6 4 1','Это строка с номером 4; в ней пять чисел.'),('0','1','Начальная строка состоит из одной единицы.')])
add('catalan','Найдите число правильных скобочных последовательностей из N пар круглых скобок. В такой последовательности в любом начальном фрагменте открывающих скобок не меньше, чем закрывающих, а во всей строке их количества равны. Это число Каталана с индексом N; для N = 0 учитывается одна пустая последовательность.',
    'Дано целое число N (0 ≤ N ≤ 1000).',MOD_OUTPUT,
    [('3','5','Последовательности: ((())), (()()), (())(), ()(()), ()()().'),('0','1','Пустая последовательность является правильной.')])

SEARCH_INPUT='В первой строке даны N и X (1 ≤ N ≤ 100000, −10^9 ≤ X ≤ 10^9). Во второй строке даны N целых чисел от −10^9 до 10^9, упорядоченных по неубыванию.'
add('find','В упорядоченном массиве с попарно различными элементами найдите число X. Позиции элементов нумеруются от 1 до N.',SEARCH_INPUT+' Все элементы массива попарно различны.',
    'Если X присутствует, выведите номер его позиции. Иначе выведите `-1`.',
    [('4 5\n-2 1 5 9','3','Число 5 находится на третьей позиции.'),('3 4\n1 3 8','-1','Число 4 отсутствует.')])
add('lower_bound','В упорядоченном массиве найдите наименьшее значение, которое не меньше X. Значения могут повторяться. Требуется само значение, а не номер позиции.',SEARCH_INPUT,
    'Выведите наименьший элемент, удовлетворяющий условию aᵢ ≥ X. Если такого элемента нет, выведите `NONE` заглавными латинскими буквами.',
    [('4 4\n1 3 5 5','5','Наименьшее значение не меньше 4 равно 5.'),('3 9\n1 3 8','NONE','Все элементы меньше 9.')])
add('at_least','В упорядоченном массиве посчитайте элементы, значение которых не меньше X. Каждый подходящий элемент учитывается отдельно, включая повторения.',SEARCH_INPUT,
    'Выведите количество индексов i, для которых aᵢ ≥ X.',
    [('5 3\n1 3 3 7 8','4','Подходят оба вхождения 3, а также 7 и 8.'),('3 9\n1 3 8','0','Подходящих элементов нет.')])
for key,power,word,samples in [
 ('isqrt','2','квадратного',[('15','3','3² ≤ 15, но 4² > 15.'),('16','4','16 — точный квадрат 4.')]),
 ('icbrt','3','кубического',[('26','2','2³ ≤ 26, но 3³ > 26.'),('27','3','27 — точный куб 3.')]),
]:
    add(key,'Найдите целую часть '+word+' корня неотрицательного целого числа N. Это наибольшее целое неотрицательное X, для которого X^'+power+' ≤ N. Ответ округляется вниз, а не к ближайшему целому.',
        'Дано целое число N (0 ≤ N ≤ 10^18).','Выведите одно целое число X.',samples)

add('nn26-bells','В университете первый звонок дня звучит в 08:00, затем звонки повторяются каждые 90 минут: 09:30, 11:00 и так далее до конца суток. По текущему времени определите, сколько звонков уже прозвучало сегодня. Звонок, совпадающий с указанным временем, тоже считается. До 08:00 ответ равен нулю.',
    'В одной строке даны два целых числа H и M — часы и минуты текущего времени (0 ≤ H ≤ 23, 0 ≤ M ≤ 59).',
    'Выведите количество звонков с начала текущих суток по указанное время включительно.',
    [('9 30','2','Уже прозвучали звонки в 08:00 и в 09:30.'),('7 59','0','Первый звонок ещё не прозвучал.')])
add('nn26-desks','В аудитории N парт. За одной партой могут сидеть либо два студента, либо один преподаватель; преподаватель занимает парту целиком. Сначала каждый из P преподавателей получает отдельную парту. Затем S студентов рассаживают по оставшимся партам максимально плотно: по двое, кроме, возможно, последнего студента. Если мест не хватает, лишние студенты остаются стоять. Определите количество полностью свободных парт.',
    'В одной строке даны целые N, S и P: количество парт, студентов и преподавателей (1 ≤ N ≤ 10^9, 0 ≤ S ≤ 2 · 10^9, 0 ≤ P ≤ N).',
    'Выведите одно целое число — количество парт, за которыми никто не сидит.',
    [('10 6 2','5','Преподаватели занимают 2 парты, шесть студентов — ещё 3. Свободны 5 парт.'),('3 5 0','0','Студенты занимают парты группами 2, 2 и 1. Все сидят, свободных парт нет.'),('2 5 1','0','После преподавателя остаётся одна парта для двух студентов; трое стоят. Свободных парт нет.')])
add('nn26-abiturients','Дан список абитуриентов: для каждого указаны имя и вступительный балл. Упорядочите список по возрастанию балла. При равных баллах имена должны идти в обратном лексикографическом порядке. Сравнение имён чувствительно к регистру: в прямом порядке буквы A–Z идут перед a–z; если одно имя является началом другого, более короткое идёт раньше. Для задачи этот порядок нужно обратить. Полностью одинаковые записи сохраняются.',
    'В первой строке дано N (1 ≤ N ≤ 100000). В каждой из следующих N строк записаны имя из 1–30 латинских букв и целый балл от 0 до 100, разделённые пробелом.',
    'Выведите N строк в требуемом порядке. В каждой строке укажите имя и балл через пробел.',
    [('4\nAiperi 65\nTilek 70\nSamat 65\nCholpon 70','Samat 65\nAiperi 65\nTilek 70\nCholpon 70','Сначала идут баллы 65. В каждой группе имя с большим лексикографическим значением идёт первым.'),('2\nAnna 90\nanna 90','anna 90\nAnna 90','Строчная a в прямом порядке идёт после заглавной A; при обратном порядке anna идёт первой.')])
add('nn26-digitsort','Упорядочите положительные целые числа по возрастанию суммы их десятичных цифр. Если суммы цифр равны, первым должно идти большее число. Повторяющиеся числа сохраняются в исходном количестве.',
    'В первой строке дано N (1 ≤ N ≤ 100000). Во второй строке даны N целых чисел aᵢ (1 ≤ aᵢ ≤ 10^9).',
    'Выведите N чисел через пробел в требуемом порядке.',
    [('6\n12 21 100 1 10 13','100 10 1 21 12 13','Сумма цифр у 100, 10 и 1 равна 1; у 21 и 12 — 3; у 13 — 4. Внутри групп числа идут по убыванию.'),('3\n9 18 9','18 9 9','У всех чисел сумма цифр равна 9. Сначала выводится 18, оба вхождения 9 сохраняются.')])
add('nn26-trails','Между N пунктами проложены M троп. Каждая тропа соединяет два пункта, имеет положительную длину и допускает движение в обе стороны. Найдите минимальную суммарную длину пути из пункта 1 в пункт N. Некоторые пункты могут быть недостижимы; между одной парой пунктов может быть несколько троп. Тропы из пункта в него же также допустимы.',
    'В первой строке даны N и M (2 ≤ N ≤ 100000, 0 ≤ M ≤ 200000). В каждой из следующих M строк даны u, v и w: номера концов тропы и её длина (1 ≤ u, v ≤ N, 1 ≤ w ≤ 10000).',
    'Выведите длину кратчайшего пути из 1 в N. Если такого пути нет, выведите `-1`.',
    [('5 6\n1 2 4\n1 3 2\n2 3 1\n2 4 5\n3 4 8\n4 5 3','11','Кратчайший путь: 1 → 3 → 2 → 4 → 5. Длина равна 2 + 1 + 5 + 3 = 11.'),('3 1\n1 2 5','-1','Из пункта 1 нельзя добраться до пункта 3.')])
add('nn26-pik-lenin','Альпинист планирует тренировочные подъёмы в течение N дней. В день i он может один раз подняться на hᵢ метров, затратив eᵢ единиц энергии, или пропустить подъём. Начальный запас энергии равен E; отдых его не восстанавливает. Выберите дни так, чтобы суммарные затраты не превышали E, а суммарный набор высоты был наибольшим. Набор высоты считается от нуля и не ограничивается высотой какой-либо вершины. Подъём с нулевыми затратами тоже можно выполнить лишь один раз.',
    'В первой строке даны N и E (1 ≤ N ≤ 500, 1 ≤ E ≤ 5000). В каждой из следующих N строк даны целые hᵢ и eᵢ (1 ≤ hᵢ ≤ 10000, 0 ≤ eᵢ ≤ 10000). Затраты отдельного подъёма могут превышать весь запас E — такой подъём выполнить нельзя.',
    'Выведите максимальный суммарный набор высоты. Если нельзя выполнить ни одного подъёма, выведите 0.',
    [('3 5\n3 2\n4 3\n5 5','7','Подъёмы в первые два дня требуют 2 + 3 = 5 энергии и дают 3 + 4 = 7 метров.'),('1 1\n100 5','0','Единственный подъём требует больше энергии, чем имеется.'),('2 1\n4 0\n3 1','7','Можно выполнить оба подъёма, потратив одну единицу энергии.')])
